(13, 'Lắc Tay Mã Não Đỏ Tinh Xảo Phong Thủy', 'lac-tay-ma-nao-do-tinh-xao-phong-thuy-13', 'PC-LT-013', 'Lắc Tay làm từ mã não đỏ thiên nhiên, hỗ trợ mệnh Hỏa. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Lắc Tay mã não đỏ, hợp mệnh Hỏa, phong cách tinh xảo.', 43, 37, 4912000.0, NULL, TRUE, 50, '{"material": "mã não đỏ", "element": "Hỏa", "origin": "Việt Nam", "style": "Tinh Xảo"}', 'active', 'pending'),
(14, 'Tỳ Hưu Thạch Anh Hồng Độc Đáo Phong Thủy', 'ty-huu-thach-anh-hong-doc-dao-phong-thuy-14', 'PC-TH-014', 'Tỳ Hưu làm từ thạch anh hồng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế độc đáo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tỳ Hưu thạch anh hồng, hợp mệnh Kim, Thổ, phong cách độc đáo.', 11, 9, 11246000.0, 10115000.0, TRUE, 54, '{"material": "thạch anh hồng", "element": "Kim, Thổ", "origin": "Brazil", "style": "Độc Đáo"}', 'active', 'pending'),
(15, 'Charm Phong Thủy Turquoise Ngọc Lam Tinh Xảo', 'charm-phong-thuy-turquoise-ngoc-lam-tinh-xao-15', 'PC-CM-015', 'Charm Phong Thủy làm từ turquoise ngọc lam thiên nhiên, hỗ trợ mệnh Mộc, Thủy. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Iran, chọn lọc kỹ càng đảm bảo chất lượng.', 'Charm Phong Thủy turquoise ngọc lam, hợp mệnh Mộc, Thủy, phong cách tinh xảo.', 14, 9, 1618000.0, 1249000.0, TRUE, 80, '{"material": "turquoise ngọc lam", "element": "Mộc, Thủy", "origin": "Iran", "style": "Tinh Xảo"}', 'active', 'pending'),
(16, 'Dây Chuyền Vàng 18K Cổ Điển Phong Thủy', 'day-chuyen-vang-18k-co-dien-phong-thuy-16', 'PC-DC-016', 'Dây Chuyền làm từ vàng 18K thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế cổ điển, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Dây Chuyền vàng 18K, hợp mệnh Kim, Thổ, phong cách cổ điển.', 6, 39, 5944000.0, NULL, TRUE, 59, '{"material": "vàng 18K", "element": "Kim, Thổ", "origin": "Việt Nam", "style": "Cổ Điển"}', 'active', 'pending'),
(17, 'Tượng Phật & Quan Âm Thạch Anh Vàng Citrine Quý Phái Phong Thủy', 'tuong-phat-quan-am-thach-anh-vang-citrine-quy-phai-phong-thuy-17', 'PC-PQ-017', 'Tượng Phật & Quan Âm làm từ thạch anh vàng citrine thiên nhiên, hỗ trợ mệnh Thổ, Kim. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tượng Phật & Quan Âm thạch anh vàng citrine, hợp mệnh Thổ, Kim, phong cách quý phái.', 50, 1, 10889000.0, NULL, TRUE, 68, '{"material": "thạch anh vàng citrine", "element": "Thổ, Kim", "origin": "Brazil", "style": "Quý Phái"}', 'active', 'pending'),
