(25, 'Tỳ Hưu Hổ Phách Amber Tối Giản Phong Thủy', 'ty-huu-ho-phach-amber-toi-gian-phong-thuy-25', 'PC-TH-025', 'Tỳ Hưu làm từ hổ phách amber thiên nhiên, hỗ trợ mệnh Thổ. Thiết kế tối giản, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tỳ Hưu hổ phách amber, hợp mệnh Thổ, phong cách tối giản.', 11, 8, 3588000.0, 3113000.0, TRUE, 29, '{"material": "hổ phách amber", "element": "Thổ", "origin": "Việt Nam", "style": "Tối Giản"}', 'active', 'pending'),
(26, 'Hoa Tai Đá Mắt Hổ Vàng Thanh Lịch Phong Thủy', 'hoa-tai-da-mat-ho-vang-thanh-lich-phong-thuy-26', 'PC-HT-026', 'Hoa Tai làm từ đá mắt hổ vàng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế thanh lịch, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nam Phi, chọn lọc kỹ càng đảm bảo chất lượng.', 'Hoa Tai đá mắt hổ vàng, hợp mệnh Kim, Thổ, phong cách thanh lịch.', 41, 46, 1147000.0, 867000.0, TRUE, 42, '{"material": "đá mắt hổ vàng", "element": "Kim, Thổ", "origin": "Nam Phi", "style": "Thanh Lịch"}', 'active', 'pending'),
