(36, 'Vòng Tay Đá Rhodonite Hồng Hiện Đại Phong Thủy', 'vong-tay-da-rhodonite-hong-hien-dai-phong-thuy-36', 'PC-VT-036', 'Vòng Tay làm từ đá rhodonite hồng thiên nhiên, hỗ trợ mệnh Hỏa, Thổ. Thiết kế hiện đại, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nga, chọn lọc kỹ càng đảm bảo chất lượng.', 'Vòng Tay đá rhodonite hồng, hợp mệnh Hỏa, Thổ, phong cách hiện đại.', 4, 4, 8879000.0, 8174000.0, TRUE, 20, '{"material": "đá rhodonite hồng", "element": "Hỏa, Thổ", "origin": "Nga", "style": "Hiện Đại"}', 'active', 'pending'),
(37, 'Vòng Tay Hổ Phách Amber Thanh Lịch Phong Thủy', 'vong-tay-ho-phach-amber-thanh-lich-phong-thuy-37', 'PC-VT-037', 'Vòng Tay làm từ hổ phách amber thiên nhiên, hỗ trợ mệnh Thổ. Thiết kế thanh lịch, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Vòng Tay hổ phách amber, hợp mệnh Thổ, phong cách thanh lịch.', 4, 12, 9039000.0, NULL, TRUE, 30, '{"material": "hổ phách amber", "element": "Thổ", "origin": "Việt Nam", "style": "Thanh Lịch"}', 'active', 'pending'),
(38, 'Charm Phong Thủy Ngọc Bích Xanh Đặc Biệt', 'charm-phong-thuy-ngoc-bich-xanh-dac-biet-38', 'PC-CM-038', 'Charm Phong Thủy làm từ ngọc bích xanh thiên nhiên, hỗ trợ mệnh Mộc, Thủy. Thiết kế đặc biệt, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Myanmar, chọn lọc kỹ càng đảm bảo chất lượng.', 'Charm Phong Thủy ngọc bích xanh, hợp mệnh Mộc, Thủy, phong cách đặc biệt.', 14, 16, 9397000.0, 8145000.0, TRUE, 66, '{"material": "ngọc bích xanh", "element": "Mộc, Thủy", "origin": "Myanmar", "style": "Đặc Biệt"}', 'active', 'pending'),
(39, 'Trâm Cài Thạch Anh Vàng Citrine Tinh Xảo Phong Thủy', 'tram-cai-thach-anh-vang-citrine-tinh-xao-phong-thuy-39', 'PC-TC-039', 'Trâm Cài làm từ thạch anh vàng citrine thiên nhiên, hỗ trợ mệnh Thổ, Kim. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Trâm Cài thạch anh vàng citrine, hợp mệnh Thổ, Kim, phong cách tinh xảo.', 13, 43, 3793000.0, 3354000.0, TRUE, 38, '{"material": "thạch anh vàng citrine", "element": "Thổ, Kim", "origin": "Brazil", "style": "Tinh Xảo"}', 'active', 'pending'),
(40, 'Tỳ Hưu Garnet Đỏ Thanh Lịch Phong Thủy', 'ty-huu-garnet-do-thanh-lich-phong-thuy-40', 'PC-TH-040', 'Tỳ Hưu làm từ garnet đỏ thiên nhiên, hỗ trợ mệnh Hỏa. Thiết kế thanh lịch, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Ấn Độ, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tỳ Hưu garnet đỏ, hợp mệnh Hỏa, phong cách thanh lịch.', 47, 1, 9423000.0, NULL, TRUE, 12, '{"material": "garnet đỏ", "element": "Hỏa", "origin": "Ấn Độ", "style": "Thanh Lịch"}', 'active', 'pending'),
(41, 'Nhẫn San Hô Đỏ Tinh Xảo Phong Thủy', 'nhan-san-ho-do-tinh-xao-phong-thuy-41', 'PC-NH-041', 'Nhẫn làm từ san hô đỏ thiên nhiên, hỗ trợ mệnh Hỏa. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Địa Trung Hải, chọn lọc kỹ càng đảm bảo chất lượng.', 'Nhẫn san hô đỏ, hợp mệnh Hỏa, phong cách tinh xảo.', 36, 33, 2230000.0, 1703000.0, TRUE, 31, '{"material": "san hô đỏ", "element": "Hỏa", "origin": "Địa Trung Hải", "style": "Tinh Xảo"}', 'active', 'pending'),
(42, 'Trâm Cài Aquamarine Xanh Biển Sang Trọng Phong Thủy', 'tram-cai-aquamarine-xanh-bien-sang-trong-phong-thuy-42', 'PC-TC-042', 'Trâm Cài làm từ aquamarine xanh biển thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế sang trọng, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Trâm Cài aquamarine xanh biển, hợp mệnh Thủy, phong cách sang trọng.', 13, 29, 9284000.0, NULL, TRUE, 83, '{"material": "aquamarine xanh biển", "element": "Thủy", "origin": "Brazil", "style": "Sang Trọng"}', 'active', 'pending'),
(43, 'Tượng Phật & Quan Âm Đá Mắt Hổ Vàng Quý Phái Phong Thủy', 'tuong-phat-quan-am-da-mat-ho-vang-quy-phai-phong-thuy-43', 'PC-PQ-043', 'Tượng Phật & Quan Âm làm từ đá mắt hổ vàng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nam Phi, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tượng Phật & Quan Âm đá mắt hổ vàng, hợp mệnh Kim, Thổ, phong cách quý phái.', 50, 20, 1805000.0, NULL, TRUE, 33, '{"material": "đá mắt hổ vàng", "element": "Kim, Thổ", "origin": "Nam Phi", "style": "Quý Phái"}', 'active', 'pending'),
(44, 'Nhẫn Ngọc Bích Xanh Quý Phái Phong Thủy', 'nhan-ngoc-bich-xanh-quy-phai-phong-thuy-44', 'PC-NH-044', 'Nhẫn làm từ ngọc bích xanh thiên nhiên, hỗ trợ mệnh Mộc, Thủy. Thiết kế quý phái, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Myanmar, chọn lọc kỹ càng đảm bảo chất lượng.', 'Nhẫn ngọc bích xanh, hợp mệnh Mộc, Thủy, phong cách quý phái.', 36, 10, 4427000.0, 3624000.0, TRUE, 87, '{"material": "ngọc bích xanh", "element": "Mộc, Thủy", "origin": "Myanmar", "style": "Quý Phái"}', 'active', 'pending'),
(45, 'Lắc Tay Hổ Phách Amber Tối Giản Phong Thủy', 'lac-tay-ho-phach-amber-toi-gian-phong-thuy-45', 'PC-LT-045', 'Lắc Tay làm từ hổ phách amber thiên nhiên, hỗ trợ mệnh Thổ. Thiết kế tối giản, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Việt Nam, chọn lọc kỹ càng đảm bảo chất lượng.', 'Lắc Tay hổ phách amber, hợp mệnh Thổ, phong cách tối giản.', 8, 17, 1639000.0, 1320000.0, FALSE, 0, '{"material": "hổ phách amber", "element": "Thổ", "origin": "Việt Nam", "style": "Tối Giản"}', 'active', 'pending'),
(46, 'Trâm Cài Đá Labradorite Sang Trọng Phong Thủy', 'tram-cai-da-labradorite-sang-trong-phong-thuy-46', 'PC-TC-046', 'Trâm Cài làm từ đá labradorite thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế sang trọng, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Madagascar, chọn lọc kỹ càng đảm bảo chất lượng.', 'Trâm Cài đá labradorite, hợp mệnh Thủy, phong cách sang trọng.', 13, 41, 2658000.0, 2369000.0, TRUE, 71, '{"material": "đá labradorite", "element": "Thủy", "origin": "Madagascar", "style": "Sang Trọng"}', 'active', 'pending'),
(47, 'Vòng Tay Ngọc Bích Xanh Thanh Lịch Phong Thủy', 'vong-tay-ngoc-bich-xanh-thanh-lich-phong-thuy-47', 'PC-VT-047', 'Vòng Tay làm từ ngọc bích xanh thiên nhiên, hỗ trợ mệnh Mộc, Thủy. Thiết kế thanh lịch, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Myanmar, chọn lọc kỹ càng đảm bảo chất lượng.', 'Vòng Tay ngọc bích xanh, hợp mệnh Mộc, Thủy, phong cách thanh lịch.', 4, 45, 8311000.0, NULL, TRUE, 74, '{"material": "ngọc bích xanh", "element": "Mộc, Thủy", "origin": "Myanmar", "style": "Thanh Lịch"}', 'active', 'pending'),
(48, 'Tượng Phật & Quan Âm Thạch Anh Hồng Cổ Điển Phong Thủy', 'tuong-phat-quan-am-thach-anh-hong-co-dien-phong-thuy-48', 'PC-PQ-048', 'Tượng Phật & Quan Âm làm từ thạch anh hồng thiên nhiên, hỗ trợ mệnh Kim, Thổ. Thiết kế cổ điển, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Brazil, chọn lọc kỹ càng đảm bảo chất lượng.', 'Tượng Phật & Quan Âm thạch anh hồng, hợp mệnh Kim, Thổ, phong cách cổ điển.', 12, 9, 4818000.0, NULL, TRUE, 5, '{"material": "thạch anh hồng", "element": "Kim, Thổ", "origin": "Brazil", "style": "Cổ Điển"}', 'active', 'pending'),
(49, 'Trâm Cài Lapis Lazuli Tinh Xảo Phong Thủy', 'tram-cai-lapis-lazuli-tinh-xao-phong-thuy-49', 'PC-TC-049', 'Trâm Cài làm từ lapis lazuli thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế tinh xảo, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Afghanistan, chọn lọc kỹ càng đảm bảo chất lượng.', 'Trâm Cài lapis lazuli, hợp mệnh Thủy, phong cách tinh xảo.', 13, 43, 5486000.0, NULL, TRUE, 52, '{"material": "lapis lazuli", "element": "Thủy", "origin": "Afghanistan", "style": "Tinh Xảo"}', 'active', 'pending'),
(50, 'Dây Chuyền Ngọc Trai Akoya Sang Trọng Phong Thủy', 'day-chuyen-ngoc-trai-akoya-sang-trong-phong-thuy-50', 'PC-DC-050', 'Dây Chuyền làm từ ngọc trai Akoya thiên nhiên, hỗ trợ mệnh Thủy. Thiết kế sang trọng, phù hợp làm quà tặng hoặc dùng hàng ngày. Nguồn gốc Nhật Bản, chọn lọc kỹ càng đảm bảo chất lượng.', 'Dây Chuyền ngọc trai Akoya, hợp mệnh Thủy, phong cách sang trọng.', 38, 12, 645000.0, NULL, TRUE, 42, '{"material": "ngọc trai Akoya", "element": "Thủy", "origin": "Nhật Bản", "style": "Sang Trọng"}', 'active', 'pending');
