(45, 33, 31, NULL, 5, 'Sản phẩm ổn nhưng giao hơi chậm', 'Rất ưng ý với moonstone đá mặt trăng, cảm giác đeo vào thấy tự tin và may mắn hơn hẳn.', TRUE, TRUE, 'pending'),
