(51, 43, 55, NULL, 5, 'Chất lượng tuyệt vời', 'Rất ưng ý với thạch anh vàng citrine, cảm giác đeo vào thấy tự tin và may mắn hơn hẳn.', TRUE, TRUE, 'pending'),
